# Firestore isolation via a namespace root document

All Firestore data is isolated by `FIRESTORE_NAMESPACE` (`dev`, `prod`, or a disposable `test-<random>`) by hanging **every** collection off a single root document — `ns/{namespace}` — rather than by prefixing top-level collection names (`${ns}__runs`, …). One `nsDoc()` function returns `db.doc('ns/' + FIRESTORE_NAMESPACE)` and all paths (`runs/{runId}`, `runs/{runId}/jobs/{evalId}`, `seen/{jobKey}`, `users/{uid}`) are built from it. `seen` sits beside `runs`, not under a run, because dedupe spans runs (D15).

## Considered Options

- **Namespace root document (chosen).** A whole namespace is one subtree, so a test run tears itself down with a single `firestore.recursiveDelete(nsDoc())`, and there is no way for a query to accidentally span namespaces — the prefix is structural, not a string every call site must remember to apply.
- **Prefixed top-level collections** (`${ns}__runs`). Rejected: isolation depends on every call site using the prefix correctly, and cleaning a `test-*` namespace means enumerating and deleting each prefixed collection separately.

## Consequences

- Per-run evaluations are a subcollection of their run (`runs/{runId}/jobs`); the evaluation doc id and the seen key are the same `jobKey` string (`${ats}:${board}:${jobId}`, D14).
- Reads/writes carry one extra path segment; negligible, and never exposed outside the repository adapter.
- The in-memory repository mirrors the same logical layout so the two implementations stay swappable.
/**
 * The persistence port the whole backend depends on — never `firebase-admin`
 * directly (CLAUDE.md, Persistence port). Two implementations satisfy it: the
 * Firestore adapter and an in-memory twin with the same subscription behaviour.
 * A single shared contract suite exercises both so they cannot drift.
 *
 * This is a backend-only port: the browser never sees a `Repo` (it talks HTTP
 * and SSE). The document shapes it moves — {@link Run}, {@link Evaluation} and
 * friends — live in `contract.ts` because those *do* travel to the browser.
 */
import type {
  Evaluation,
  EvaluationStatus,
  Run,
  RunFunnel,
  RunStatus,
  UserDoc,
  Verdict,
} from "./contract.js";

/** Returned by every `watch*` call; stops delivery and releases the listener. */
export type Unsubscribe = () => void;

/**
 * A forward-only patch to a Run. `funnelIncrements` are *added* to the current
 * counts — never an overwrite — so the Firestore adapter can map them to
 * `FieldValue.increment` (CODING_STANDARDS landmine: lost updates). `updatedAt`
 * is set by the adapter, not the caller.
 */
export interface RunDelta {
  status?: RunStatus;
  reason?: string | null;
  funnelIncrements?: Partial<RunFunnel>;
}

/** A patch to a single Evaluation. `updatedAt` is set by the adapter. */
export interface EvaluationDelta {
  status?: EvaluationStatus;
  verdict?: Verdict | null;
  score?: number | null;
  reason?: string | null;
}

/** Mirrors a Firestore collection change: how an Evaluation entered the stream. */
export type ChangeType = "added" | "modified" | "removed";

export interface EvaluationChange {
  type: ChangeType;
  evaluation: Evaluation;
}

/**
 * Thrown by `createRun` when the user already has an active Run. The route maps
 * it to `409` — one active run per user (D17). Carries the offending run id so
 * callers and logs can name it.
 */
export class ActiveRunExistsError extends Error {
  constructor(
    readonly uid: string,
    readonly activeRunId: string,
  ) {
    super(`user ${uid} already has an active run (${activeRunId})`);
    this.name = "ActiveRunExistsError";
  }
}

/**
 * The persistence contract. Writes echo back to live subscribers; each `watch*`
 * delivers an initial snapshot on a microtask (never synchronously), then one
 * callback per subsequent matching write, in write order.
 */
export interface Repo {
  getUser(uid: string): Promise<UserDoc | null>;
  /** Seeds the user on first boot (D13); a no-op if the document already exists. */
  seedUserIfMissing(uid: string, doc: UserDoc): Promise<void>;

  /** Creates a Run; rejects with {@link ActiveRunExistsError} if one is active (D17). */
  createRun(run: Run): Promise<void>;
  getActiveRun(uid: string): Promise<Run | null>;
  patchRun(runId: string, delta: RunDelta): Promise<void>;

  putEvaluation(runId: string, evaluation: Evaluation): Promise<void>;
  patchEvaluation(runId: string, jobKey: string, delta: EvaluationDelta): Promise<void>;

  /** Seen spans Runs so dedupe survives across them (GLOSSARY: Seen, D15). */
  isSeen(jobKey: string): Promise<boolean>;
  markSeen(jobKey: string): Promise<void>;

  watchRun(runId: string, cb: (run: Run) => void): Unsubscribe;
  watchEvaluations(runId: string, cb: (change: EvaluationChange) => void): Unsubscribe;
}
import { z } from "zod";

/**
 * Environment is parsed once, at startup, and the process fails fast if it is
 * invalid (CODING_STANDARDS, General). Later tickets add the Firebase, auth,
 * CORS and AI vars; this skeleton only needs enough to boot and serve health.
 */
const envSchema = z.object({
  NODE_ENV: z.enum(["development", "test", "production"]).default("development"),
  PORT: z.coerce.number().int().positive().default(3001),
  FIRESTORE_NAMESPACE: z.string().min(1).default("dev"),
});

export type Config = z.infer<typeof envSchema>;

export function loadConfig(env: NodeJS.ProcessEnv = process.env): Config {
  const config = envSchema.parse({
    NODE_ENV: env.NODE_ENV,
    PORT: env.PORT,
    FIRESTORE_NAMESPACE: env.FIRESTORE_NAMESPACE,
  });

  // The `prod` namespace is only ever used on the server (CODING_STANDARDS,
  // Namespace isolation).
  if (config.FIRESTORE_NAMESPACE === "prod" && config.NODE_ENV !== "production") {
    throw new Error("Refusing to start: FIRESTORE_NAMESPACE=prod requires NODE_ENV=production");
  }

  return config;
}
import { loadConfig } from "./config.js";
import { createApp } from "./app.js";
import { logger } from "./logger.js";

const config = loadConfig();
const app = createApp(config);

app.listen(config.PORT, () => {
  logger.info("api_listening", {
    port: config.PORT,
    namespace: config.FIRESTORE_NAMESPACE,
  });
});
import express, { type Request, type Response, type NextFunction } from "express";
import cors from "cors";
import {
  errorResponseSchema,
  healthResponseSchema,
  type HealthResponse,
} from "@auto-apply/shared";
import type { Config } from "./config.js";
import { logger } from "./logger.js";

/**
 * Builds the Express app. Kept separate from `index.ts` so tests can drive it
 * with Supertest without opening a socket. Routes stay thin: later tickets add
 * the run routes and the SSE stream here.
 */
export function createApp(config: Config) {
  const app = express();

  // Behind nginx in production (CLAUDE.md, Deployment).
  app.set("trust proxy", 1);

  // Permissive dev CORS so web (5173) can call api (3001). Tightened to an
  // exact origin with credentials in ticket 15 (D27).
  app.use(cors());

  app.use(express.json({ limit: "100kb" }));

  app.get("/api/health", (_req: Request, res: Response) => {
    const body: HealthResponse = {
      status: "ok",
      service: "auto-apply-api",
      namespace: config.FIRESTORE_NAMESPACE,
      time: new Date().toISOString(),
    };
    res.json(healthResponseSchema.parse(body));
  });

  // Unknown routes get the shared JSON error shape, not Express's HTML default.
  app.use((_req: Request, res: Response) => {
    res.status(404).json(
      errorResponseSchema.parse({
        error: { code: "not_found", message: "Not found" },
      }),
    );
  });

  // Errors return the shared JSON shape, never a stack trace (CODING_STANDARDS).
  app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
    logger.error("unhandled_error", {
      error: err instanceof Error ? err.message : String(err),
    });
    res.status(500).json(
      errorResponseSchema.parse({
        error: { code: "internal", message: "Internal server error" },
      }),
    );
  });

  return app;
}
/**
 * The one place the API writes diagnostics. Structured JSON lines, so there is
 * never a stray `console.log` in the codebase (CODING_STANDARDS, General).
 */
type Level = "info" | "warn" | "error";

function write(level: Level, msg: string, meta?: Record<string, unknown>): void {
  const entry = {
    level,
    msg,
    time: new Date().toISOString(),
    ...(meta ? { meta } : {}),
  };
  const line = `${JSON.stringify(entry)}\n`;
  if (level === "error") {
    process.stderr.write(line);
  } else {
    process.stdout.write(line);
  }
}

export const logger = {
  info: (msg: string, meta?: Record<string, unknown>) => write("info", msg, meta),
  warn: (msg: string, meta?: Record<string, unknown>) => write("warn", msg, meta),
  error: (msg: string, meta?: Record<string, unknown>) => write("error", msg, meta),
};
# apps/api environment. Copy to apps/api/.env and fill in.
# Node >=22 loads this file in dev via tsx; in production the server reads apps/api/.env.
# Never commit the real .env (see .gitignore). Only this example is committed.

# --- Core ---
NODE_ENV=development
PORT=3001
# Firestore isolation namespace: dev locally, prod only on the server, test-* in tests.
FIRESTORE_NAMESPACE=dev

# --- Firebase (added in a later ticket) ---
# Path to the service-account key JSON, kept OUTSIDE the repo (used locally and on EC2):
# GOOGLE_APPLICATION_CREDENTIALS=/Users/you/.secrets/auto-apply-sa.json
# ...or the key JSON inlined as one value (used in cloud sessions):
# FIREBASE_SERVICE_ACCOUNT_JSON=

# --- AI (added in a later ticket) ---
# With no AI_API_KEY the whole run uses the keyword fallback matcher (D24).
# AI_PROVIDER=deepseek
# AI_BASE_URL=https://api.deepseek.com
# AI_MODEL=deepseek-chat
# AI_API_KEY=

# --- Auth + CORS (added in a later ticket) ---
# CORS_ORIGIN=http://localhost:5173
# JWT_SECRET=
# AUTH_PASSWORD_HASH=
{
  "name": "@auto-apply/api",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "nodemon --quiet --watch src --watch ../../packages/shared/src --ext ts --exec \"tsx src/index.ts\"",
    "build": "tsc -p tsconfig.build.json",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "start": "node dist/index.js"
  },
  "dependencies": {
    "@auto-apply/shared": "*",
    "cors": "^2.8.5",
    "express": "^4.21.2",
    "zod": "^3.23.8"
  }
}
import { defineConfig } from "vitest/config";
import path from "node:path";

export default defineConfig({
  resolve: {
    alias: {
      "@auto-apply/shared": path.resolve(import.meta.dirname, "../../packages/shared/src/index.ts"),
    },
  },
  test: {
    environment: "node",
  },
});
rules_version = '2';
// Browsers never touch Firestore: the API reads and writes through the Admin SDK, which bypasses these rules.
// If an ADR moves to direct browser reads, replace this with per-user read rules plus anonymous auth.
service cloud.firestore {
  match /databases/{database}/documents {
    match /{document=**} {
      allow read, write: if false;
    }
  }
}

