import { describe, it, expect, vi, afterEach } from "vitest";
import { render, screen, waitFor, cleanup } from "@testing-library/react";
import { App } from "./App";

function mockFetch(response: Response) {
  vi.stubGlobal(
    "fetch",
    vi.fn(async () => response),
  );
}

afterEach(() => {
  cleanup();
  vi.unstubAllGlobals();
});

describe("<App />", () => {
  it("shows a loading state, then the health data on success", async () => {
    mockFetch(
      new Response(
        JSON.stringify({
          status: "ok",
          service: "auto-apply-api",
          namespace: "dev",
          time: new Date().toISOString(),
        }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      ),
    );

  });

  it("validates the health payload", () => {
    const ok = { status: "ok", service: "auto-apply-api", namespace: "dev", time: "t" };
    expect(() => healthResponseSchema.parse(ok)).not.toThrow();
    expect(() => healthResponseSchema.parse({ ...ok, status: "down" })).toThrow();
  });
});
  return (
    <main>
      <h1>AI Auto-Apply</h1>
      {state.kind === "loading" && <p role="status">Checking API…</p>}
      {state.kind === "error" && <p role="alert">Could not reach the API: {state.message}</p>}
      {state.kind === "ready" && (
        <dl>
          <dt>API status</dt>
          <dd>{state.health.status}</dd>
          <dt>Service</dt>
          <dd>{state.health.service}</dd>
          <dt>Namespace</dt>
          <dd>{state.health.namespace}</dd>
        </dl>
      )}
    </main>
  );
}

